  if ((a <= b && b <= c) || (c <= b && b <= a)) {
    return (b - a) == (c - b);
  } else if ((a <= c && c <= b) || (b <= c && c <= a)) {
    return (c - a) == (b - c);
  } else {
    return (a - b) == (c - a);
  }
}

